--liquibase formatted sql

--changeset nutro-assist:008-create-food-items
CREATE TABLE IF NOT EXISTS food_items (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    food_code            VARCHAR(255) NOT NULL,
    food_name            VARCHAR(255) NOT NULL,
    source               VARCHAR(255),
    energy_kcal          DOUBLE PRECISION,
    carbsg               DOUBLE PRECISION,
    proteing             DOUBLE PRECISION,
    fatg                 DOUBLE PRECISION,
    sugarg               DOUBLE PRECISION,
    fibreg               DOUBLE PRECISION,
    calcium_mg           DOUBLE PRECISION,
    magnesium_mg         DOUBLE PRECISION,
    sodium_mg            DOUBLE PRECISION,
    potassium_mg         DOUBLE PRECISION,
    iron_mg              DOUBLE PRECISION,
    vitc_mg              DOUBLE PRECISION,
    serving_unit         VARCHAR(255),
    serving_energy_kcal  DOUBLE PRECISION,
    serving_carbsg       DOUBLE PRECISION,
    serving_proteing     DOUBLE PRECISION,
    serving_fatg         DOUBLE PRECISION,
    serving_fibreg       DOUBLE PRECISION,
    CONSTRAINT uk_food_items_food_code UNIQUE (food_code)
);

--changeset nutro-assist:008-create-recipes
CREATE TABLE IF NOT EXISTS recipes (
    recipe_id         INTEGER PRIMARY KEY,
    recipe_name       VARCHAR(255) NOT NULL,
    recipe_url        VARCHAR(255),
    total_energy_kcal DOUBLE PRECISION,
    total_carbsg      DOUBLE PRECISION,
    total_proteing    DOUBLE PRECISION,
    total_fatg        DOUBLE PRECISION,
    total_fibreg      DOUBLE PRECISION
);

--changeset nutro-assist:008-create-recipe-ingredients
CREATE TABLE IF NOT EXISTS recipe_ingredients (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ingredient_name          VARCHAR(255),
    ingredient_standard_name VARCHAR(255),
    recipe_id                INTEGER,
    nin_id                   INTEGER,
    quantity                 DOUBLE PRECISION,
    quantity_in_gram         DOUBLE PRECISION,
    serving_unit             VARCHAR(255),
    energy_kcal              DOUBLE PRECISION,
    carbsg                   DOUBLE PRECISION,
    proteing                 DOUBLE PRECISION,
    fatg                     DOUBLE PRECISION,
    fibreg                   DOUBLE PRECISION
);
CREATE INDEX IF NOT EXISTS idx_recipe_ing_recipe_id ON recipe_ingredients(recipe_id);

